//! Rust port of `tests/test7.cpp` from earcut.hpp: triangulate a two-turn spiral
//! sampled at `2 * n` points and print the resulting triangle indices.
//!
//! Usage: `test7 [n]` — `n` defaults to 7 and is parsed with `atoi` semantics.

// `#[path]` module declarations keep this file buildable both standalone
// (`rustc test7.rs`) and as the Cargo `[[bin]]` target at the package root.
#[path = "src/cli.rs"]
mod cli;
#[path = "src/earcut/mod.rs"]
mod earcut;
#[path = "src/spiral.rs"]
mod spiral;

use std::io::Write;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 7;
    if args.len() > 1 {
        n = cli::atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let spiral = spiral::spiral(n);

    polygon.push(spiral);

    let indices = earcut::earcut(&polygon);

    // `std::cout << idx << " "` for each index: no separator logic, no trailing
    // newline.
    let mut out = String::new();
    for idx in &indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }

    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    // A failed write leaves `std::cout` in a bad state but still returns 0 from
    // main, so swallow errors rather than panicking (Rust ignores SIGPIPE, which
    // would otherwise turn a truncated pipe into a panic message on stderr).
    let _ = handle.write_all(out.as_bytes());
    let _ = handle.flush();
}

